(()=>{'use strict';const shops={todo:{name:'TodoListo.uy',category:'COMPRAS PARA TU CASA',initial:'TL',goal:5,reward:'10% en tu próxima compra',condition:'Ejemplo: productos seleccionados y condiciones a definir con el local.',rule:'Ejemplo: una compra validada, un sello.',color:'#007c91'},ciber:{name:'Ciber Universo',category:'TECNOLOGÍA CERCA',initial:'CU',goal:4,reward:'Un beneficio en accesorios',condition:'Ejemplo: descuento a definir sobre accesorios seleccionados.',rule:'Ejemplo: un servicio abonado y validado, un sello.',color:'#6551a5'},clima:{name:'Clima Perfecto',category:'CUIDÁ TU AIRE ACONDICIONADO',initial:'CP',goal:3,reward:'Beneficio en tu próximo mantenimiento',condition:'Ejemplo: importe y alcance a acordar con el instalador.',rule:'Ejemplo: un mantenimiento realizado y validado, un sello.',color:'#007eaa'}};
const key='revista-club-demo-v1';const fresh=()=>({counts:{todo:0,ciber:0,clima:0},redemptions:{todo:0,ciber:0,clima:0},history:[]});let state=fresh(),selected='todo';try{const x=JSON.parse(localStorage.getItem(key));if(x&&Object.keys(shops).every(k=>Number.isInteger(x.counts?.[k])&&x.counts[k]>=0&&x.counts[k]<=shops[k].goal&&Number.isInteger(x.redemptions?.[k])&&x.redemptions[k]>=0)&&Array.isArray(x.history))state=x}catch{}const $=id=>document.getElementById(id);function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{}}
function render(message=''){const b=shops[selected],n=state.counts[selected];$('loyalty').setAttribute('aria-labelledby','tab-'+selected);$('loyalty').style.setProperty('--accent',b.color);$('category').textContent=b.category;$('business-name').textContent=b.name;$('initial').textContent=b.initial;$('rule').textContent=b.rule;$('progress-text').textContent=n+' de '+b.goal+' sellos';$('remaining').textContent=n===b.goal?'¡Premio de prueba disponible!':'Te faltan '+(b.goal-n);$('progress-fill').style.width=n/b.goal*100+'%';const bar=document.querySelector('.progress');bar.setAttribute('aria-valuemax',b.goal);bar.setAttribute('aria-valuenow',n);$('stamps').replaceChildren();for(let i=1;i<=b.goal;i++){const el=document.createElement('span');el.className='stamp'+(i<=n?' filled':'')+(i===b.goal?' last':'');el.textContent=i<=n?'✓':i===b.goal?'✦':i;el.setAttribute('aria-label','Sello '+i+': '+(i<=n?'completo':'pendiente'));$('stamps').append(el)}$('reward-name').textContent=b.reward;$('reward-condition').textContent=b.condition;$('stamp').disabled=n>=b.goal;$('redeem').disabled=n<b.goal;$('total').textContent=Object.values(state.counts).reduce((a,b)=>a+b,0);$('redeemed').textContent=Object.values(state.redemptions).reduce((a,b)=>a+b,0);$('status').textContent=message;document.querySelectorAll('[data-business]').forEach(t=>{const active=t.dataset.business===selected;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1});$('cross-status').textContent=state.redemptions.todo?'¡Beneficio cruzado de prueba desbloqueado! Conocé Ciber Universo en la revista.':'Completá y canjeá la tarjeta de TodoListo para probarlo.';$('history').replaceChildren();const entries=state.history.length?state.history:['Todavía no hay movimientos. Elegí un local y sumá tu primer sello.'];entries.slice(0,8).forEach(t=>{const li=document.createElement('li');li.textContent=String(t);$('history').append(li)})}
document.querySelectorAll('[data-business]').forEach(t=>{t.onclick=()=>{selected=t.dataset.business;render()};t.onkeydown=e=>{const ids=Object.keys(shops);let i=ids.indexOf(selected);if(e.key==='ArrowRight')i=(i+1)%ids.length;else if(e.key==='ArrowLeft')i=(i+ids.length-1)%ids.length;else return;e.preventDefault();selected=ids[i];render();$('tab-'+selected).focus()}});$('stamp').onclick=()=>{const b=shops[selected];if(state.counts[selected]>=b.goal)return;state.counts[selected]++;state.history.unshift(b.name+' · Compra simulada: +1 sello.');save();render(state.counts[selected]===b.goal?'¡Completaste la tarjeta! Ahora podés simular el canje.':'Sello de prueba agregado. ¡Un paso más cerca!')};$('redeem').onclick=()=>{const b=shops[selected];if(state.counts[selected]<b.goal)return;state.counts[selected]=0;state.redemptions[selected]++;state.history.unshift(b.name+' · Canje simulado: '+b.reward+'.');save();render('Canje simulado. Tu tarjeta vuelve a cero para empezar otra vez.')};$('reset').onclick=()=>{state=fresh();save();render('Prueba reiniciada. Podés comenzar de nuevo.')};const dialog=$('qr-dialog');$('show-qr').onclick=()=>dialog.showModal();dialog.querySelectorAll('button').forEach(b=>b.onclick=()=>dialog.close());render()})();
